import{_ as t,o as a,c as o,a6 as n}from"./chunks/framework.BrkgobfX.js";const g=JSON.parse('{"title":"缓存","description":"Cache-Control 请求与响应指令全集、Expires/Age 与新鲜度计算公式。","frontmatter":{"title":"缓存","description":"Cache-Control 请求与响应指令全集、Expires/Age 与新鲜度计算公式。","source":"https://daiw.org/manual/http11/caching"},"headers":[],"relativePath":"manual/computer-programming/http11/caching.md","filePath":"manual/computer-programming/http11/caching.md"}'),s={name:"manual/computer-programming/http11/caching.md"};function r(d,e,c,i,l,p){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="缓存" tabindex="-1">缓存 <a class="header-anchor" href="#缓存" aria-label="Permalink to &quot;缓存&quot;">​</a></h1><p>规范基准是 <strong>RFC 9111</strong>。缓存键默认是「请求方法 + 目标 URI」，再由 <code>Vary</code> 扩展。</p><h2 id="可存储的前提" tabindex="-1">可存储的前提 <a class="header-anchor" href="#可存储的前提" aria-label="Permalink to &quot;可存储的前提&quot;">​</a></h2><p>缓存 <strong>MUST NOT</strong> 存储响应，除非全部满足：</p><ol><li>请求方法可缓存（<code>GET</code>/<code>HEAD</code>，或带显式新鲜度的 <code>POST</code>）。</li><li>响应状态码可缓存（见<a href="/Front2Full/manual/computer-programming/http11/status-codes">状态码</a>的默认可缓存列表），或有显式指令允许。</li><li>请求与响应中都<strong>无 <code>no-store</code></strong>。</li><li>若是<strong>共享缓存</strong>：响应无 <code>private</code>；且请求无 <code>Authorization</code>（除非响应带 <code>public</code>/<code>s-maxage</code>/<code>must-revalidate</code>）。</li><li>响应有以下之一：<code>Expires</code>、<code>max-age</code>、<code>s-maxage</code>（共享缓存）、可用的启发式依据、<code>public</code>。</li></ol><h2 id="cache-control-语法" tabindex="-1">Cache-Control 语法 <a class="header-anchor" href="#cache-control-语法" aria-label="Permalink to &quot;Cache-Control 语法&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control = #cache-directive</span></span>
<span class="line"><span>cache-directive = token [ &quot;=&quot; ( token / quoted-string ) ]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>指令名<strong>大小写不敏感</strong>。不认识的指令 <strong>MUST</strong> 被忽略（不影响其他指令）。<code>delta-seconds</code> 是<strong>非负十进制整数</strong>，溢出实现上限时按上限处理。</p><h2 id="响应指令" tabindex="-1">响应指令 <a class="header-anchor" href="#响应指令" aria-label="Permalink to &quot;响应指令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>语义</th></tr></thead><tbody><tr><td><code>max-age=N</code></td><td>响应在生成后 N 秒内新鲜</td></tr><tr><td><code>s-maxage=N</code></td><td>同上，<strong>仅对共享缓存</strong>，且<strong>覆盖</strong> <code>max-age</code> 与 <code>Expires</code></td></tr><tr><td><code>no-cache</code></td><td><strong>可以存储</strong>，但复用前 <strong>MUST</strong> 向源站成功验证</td></tr><tr><td><code>no-store</code></td><td><strong>MUST NOT</strong> 存储本请求或响应的任何部分</td></tr><tr><td><code>private</code></td><td>仅<strong>私有</strong>缓存可存储；共享缓存禁止</td></tr><tr><td><code>public</code></td><td>即使通常不可缓存（如带 <code>Authorization</code>）也可被共享缓存存储</td></tr><tr><td><code>must-revalidate</code></td><td>一旦陈旧，<strong>MUST NOT</strong> 在未成功验证前使用；源站不可达时 <strong>MUST</strong> 返回 <code>504</code></td></tr><tr><td><code>proxy-revalidate</code></td><td>同上，仅对共享缓存</td></tr><tr><td><code>must-understand</code></td><td>缓存仅在<strong>理解该状态码</strong>的缓存需求时才可存储；应与 <code>no-store</code> 连用作降级</td></tr><tr><td><code>no-transform</code></td><td>中间件 <strong>MUST NOT</strong> 改动体或 <code>Content-Encoding</code>/<code>Content-Type</code>/<code>Content-Range</code></td></tr></tbody></table><h3 id="no-cache-与-no-store-的区别" tabindex="-1">no-cache 与 no-store 的区别 <a class="header-anchor" href="#no-cache-与-no-store-的区别" aria-label="Permalink to &quot;no-cache 与 no-store 的区别&quot;">​</a></h3><p>高频混淆：</p><ul><li><strong><code>no-cache</code></strong>：存，但每次用前必须验证（可命中 <code>304</code>，省带宽）。</li><li><strong><code>no-store</code></strong>：<strong>根本不存</strong>，磁盘上不留痕迹。用于敏感数据。</li></ul><p>要「绝对不缓存」应发 <code>Cache-Control: no-store</code>，单发 <code>no-cache</code> 达不到目的。</p><h3 id="带参数的限定形式" tabindex="-1">带参数的限定形式 <a class="header-anchor" href="#带参数的限定形式" aria-label="Permalink to &quot;带参数的限定形式&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache-Control: no-cache=&quot;Set-Cookie&quot;</span></span>
<span class="line"><span>Cache-Control: private=&quot;X-Internal-Id&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>仅对<strong>列出的字段</strong>生效：可以复用缓存，但复用前必须移除这些字段。<strong>仅响应指令</strong>可带此参数形式；共享缓存必须支持，否则应按无参数形式（更严格）处理。</p><h3 id="扩展指令" tabindex="-1">扩展指令 <a class="header-anchor" href="#扩展指令" aria-label="Permalink to &quot;扩展指令&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指令</th><th>RFC</th><th>语义</th></tr></thead><tbody><tr><td><code>immutable</code></td><td>8246</td><td>新鲜期内即使用户强制刷新也<strong>不发验证请求</strong>。用于带哈希文件名的静态资源</td></tr><tr><td><code>stale-while-revalidate=N</code></td><td>5861</td><td>陈旧后 N 秒内可<strong>先返回旧副本</strong>，后台异步验证</td></tr><tr><td><code>stale-if-error=N</code></td><td>5861</td><td>源站返回 <code>5xx</code>/不可达时，N 秒内可继续用旧副本</td></tr></tbody></table><h2 id="请求指令" tabindex="-1">请求指令 <a class="header-anchor" href="#请求指令" aria-label="Permalink to &quot;请求指令&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指令</th><th>语义</th></tr></thead><tbody><tr><td><code>max-age=N</code></td><td>只接受年龄 ≤ N 秒的副本</td></tr><tr><td><code>max-stale[=N]</code></td><td>接受已陈旧的副本；带 N 则限制超期不超过 N 秒；不带值表示接受任意陈旧程度</td></tr><tr><td><code>min-fresh=N</code></td><td>要求副本在 N 秒内仍保持新鲜</td></tr><tr><td><code>no-cache</code></td><td>强制向源站验证后再返回（浏览器 Ctrl+F5 的行为）</td></tr><tr><td><code>no-store</code></td><td>不得存储本次请求与响应</td></tr><tr><td><code>no-transform</code></td><td>禁止中间件改动</td></tr><tr><td><code>only-if-cached</code></td><td><strong>仅</strong>返回已缓存副本；无可用副本时 <strong>MUST</strong> 返回 <code>504</code></td></tr></tbody></table><h2 id="expires" tabindex="-1">Expires <a class="header-anchor" href="#expires" aria-label="Permalink to &quot;Expires&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Expires = HTTP-date</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>绝对过期时刻。<strong>优先级低于</strong> <code>max-age</code>/<code>s-maxage</code>——两者同时存在时 <code>Cache-Control</code> 胜出（因其不受时钟偏差影响）。</p><ul><li>无效日期（含 <code>Expires: 0</code>）<strong>MUST</strong> 被解析为「已过期」。</li><li>早于 <code>Date</code> 表示已过期。</li><li>建议值不超过一年后。</li></ul><h2 id="age" tabindex="-1">Age <a class="header-anchor" href="#age" aria-label="Permalink to &quot;Age&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Age = delta-seconds</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>响应</strong>字段，由缓存添加，表示该副本自源站生成以来经过的<strong>秒数</strong>估计值。源站不发 <code>Age</code>；<code>Age: 0</code> 表示刚从源站取回。</p><h2 id="新鲜度计算" tabindex="-1">新鲜度计算 <a class="header-anchor" href="#新鲜度计算" aria-label="Permalink to &quot;新鲜度计算&quot;">​</a></h2><h3 id="freshness-lifetime-的取值顺序" tabindex="-1">freshness_lifetime 的取值顺序 <a class="header-anchor" href="#freshness-lifetime-的取值顺序" aria-label="Permalink to &quot;freshness\\_lifetime 的取值顺序&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. s-maxage        (仅共享缓存)</span></span>
<span class="line"><span>2. max-age</span></span>
<span class="line"><span>3. Expires - Date</span></span>
<span class="line"><span>4. 启发式估算</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>命中即停。</p><h3 id="current-age" tabindex="-1">current_age <a class="header-anchor" href="#current-age" aria-label="Permalink to &quot;current\\_age&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apparent_age          = max(0, response_time - date_value)</span></span>
<span class="line"><span>corrected_age_value   = age_value + (response_time - request_time)</span></span>
<span class="line"><span>corrected_initial_age = max(apparent_age, corrected_age_value)</span></span>
<span class="line"><span>current_age           = corrected_initial_age + (now - response_time)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>取 <code>max</code> 的目的是<strong>抵消时钟偏差</strong>：无论本机时钟快还是源站时钟慢，都取更保守（更老）的估计。</p><h3 id="判定" tabindex="-1">判定 <a class="header-anchor" href="#判定" aria-label="Permalink to &quot;判定&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>响应新鲜  ⟺  freshness_lifetime &gt; current_age</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>陈旧后并非不可用——除非有 <code>must-revalidate</code>/<code>no-cache</code>，缓存 <strong>MAY</strong> 在客户端允许（<code>max-stale</code>）或源站不可达（<code>stale-if-error</code>）时继续返回陈旧副本。</p><h3 id="启发式新鲜度" tabindex="-1">启发式新鲜度 <a class="header-anchor" href="#启发式新鲜度" aria-label="Permalink to &quot;启发式新鲜度&quot;">​</a></h3><p>无任何显式过期信息时，缓存 <strong>MAY</strong> 自行估算。常见做法是取 <code>(Date − Last-Modified) × 10%</code>，并设上限（如 24 小时）。</p><ul><li>仅可用于<strong>默认可缓存</strong>的状态码。</li><li>RFC 9111 <strong>移除了 <code>Warning</code> 字段</strong>（原用于标注启发式/陈旧响应），不应再发送或依赖。</li></ul><h2 id="验证与更新" tabindex="-1">验证与更新 <a class="header-anchor" href="#验证与更新" aria-label="Permalink to &quot;验证与更新&quot;">​</a></h2><p>副本陈旧后，缓存发<strong>条件请求</strong>（<code>If-None-Match</code> 优先于 <code>If-Modified-Since</code>）：</p><ul><li>收到 <code>304</code> → 用响应头<strong>更新</strong>已存副本，重置年龄，返回给客户端。</li><li>收到 <code>200</code> → 用新响应<strong>替换</strong>旧副本。</li><li>收到 <code>5xx</code> → 按 <code>stale-if-error</code> 决定返回旧副本还是透传错误；有 <code>must-revalidate</code> 时 <strong>MUST</strong> 返回 <code>504</code>。</li></ul><h2 id="失效-invalidation" tabindex="-1">失效（invalidation） <a class="header-anchor" href="#失效-invalidation" aria-label="Permalink to &quot;失效（invalidation）&quot;">​</a></h2><p>缓存 <strong>MUST</strong> 在收到<strong>非安全方法</strong>（<code>POST</code>/<code>PUT</code>/<code>DELETE</code>/<code>PATCH</code>）的<strong>成功</strong>响应后，失效以下 URI 的已存副本：</p><ol><li>请求的目标 URI。</li><li>响应中 <code>Location</code> 与 <code>Content-Location</code> 所指 URI——<strong>仅当</strong>其 origin 与目标 URI <strong>相同</strong>（防止跨站投毒）。</li></ol><p>非成功响应（4xx/5xx）<strong>不触发</strong>失效。</p><h2 id="与-authorization-的交互" tabindex="-1">与 Authorization 的交互 <a class="header-anchor" href="#与-authorization-的交互" aria-label="Permalink to &quot;与 Authorization 的交互&quot;">​</a></h2><p>带 <code>Authorization</code> 的请求，其响应<strong>默认不可被共享缓存存储</strong>。仅当响应显式带 <code>public</code>、<code>s-maxage</code> 或 <code>must-revalidate</code> 时才允许——这是防止把 A 用户的私有数据发给 B 用户的关键防线。</p><p>下一篇：<a href="/Front2Full/manual/computer-programming/http11/authentication">认证</a>——挑战语法与 Authorization 字段。</p>`,51)])])}const u=t(s,[["render",r]]);export{g as __pageData,u as default};
